Here is a complete, minimal, and secure implementation using **Node.js**, **Express**, and **SQLite**. 

It stores uploaded files in a private directory (outside the public folder) and stores passwords using **bcrypt** hashes. The server handles verification and only streams the file after validating the password.

---

### 1. Setup the Project

Create a new directory and install the necessary dependencies:

```bash
mkdir secure-share
cd secure-share
npm init -y
npm install express multer bcryptjs better-sqlite3 uuid
```

Create two directories:
```bash
mkdir uploads public
```

---

### 2. Server Code (`server.js`)

Create a file named `server.js`:

```javascript
const express = require('express');
const multer = require('multer');
const bcrypt = require('bcryptjs');
const Database = require('better-sqlite3');
const { v4: uuidv4 } = require('uuid');
const path = require('path');
const fs = require('fs');

const app = express();
const db = new Database('files.db');

// Parse JSON and form data
app.use(express.urlencoded({ extended: true }));
app.use(express.json());

// Serve static frontend assets (HTML, CSS, client-side JS)
app.use(express.static('public'));

// Setup SQLite Database
db.exec(`
  CREATE TABLE IF NOT EXISTS files (
    id TEXT PRIMARY KEY,
    filename TEXT,
    original_name TEXT,
    password_hash TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`);

// Multer storage setup (Store files in a private 'uploads' folder)
const upload = multer({
  dest: path.join(__dirname, 'uploads'),
  limits: { fileSize: 50 * 1024 * 1024 } // 50MB limit
});

// 1. Upload Route
app.post('/api/upload', upload.single('file'), async (req, res) => {
  try {
    const { password } = req.body;
    const file = req.file;

    if (!file || !password) {
      return res.status(400).send('File and password are required.');
    }

    // Hash the password
    const saltRounds = 10;
    const passwordHash = await bcrypt.hash(password, saltRounds);

    // Generate unique share ID
    const shareId = uuidv4();

    // Store file metadata in the database
    const insert = db.prepare(`
      INSERT INTO files (id, filename, original_name, password_hash)
      VALUES (?, ?, ?, ?)
    `);
    insert.run(shareId, file.filename, file.originalname, passwordHash);

    // Return the link
    res.json({ link: `/download.html?id=${shareId}` });
  } catch (err) {
    console.error(err);
    res.status(500).send('Upload failed.');
  }
});

// 2. Download Route (Server-side validation)
app.post('/api/download/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const { password } = req.body;

    // Look up file record
    const fileRecord = db.prepare('SELECT * FROM files WHERE id = ?').get(id);

    if (!fileRecord) {
      return res.status(404).send('File not found or link expired.');
    }

    // Compare provided password with stored hash
    const match = await bcrypt.compare(password, fileRecord.password_hash);
    if (!match) {
      return res.status(401).send('Incorrect password.');
    }

    // Resolve file path
    const filePath = path.join(__dirname, 'uploads', fileRecord.filename);

    if (!fs.existsSync(filePath)) {
      return res.status(404).send('File missing from storage.');
    }

    // Stream the file directly to the client
    res.download(filePath, fileRecord.original_name);
  } catch (err) {
    console.error(err);
    res.status(500).send('Download error.');
  }
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

---

### 3. Frontend Pages

#### Upload Page (`public/index.html`)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Password Protected File Share</title>
  <style>
    body { font-family: sans-serif; max-width: 500px; margin: 50px auto; padding: 20px; }
    form { display: flex; flex-direction: column; gap: 10px; }
  </style>
</head>
<body>
  <h2>Upload a Protected File</h2>
  <form id="uploadForm">
    <label>Choose File:</label>
    <input type="file" name="file" required>

    <label>Set Password:</label>
    <input type="password" name="password" required>

    <button type="submit">Upload</button>
  </form>

  <div id="result" style="margin-top: 20px;"></div>

  <script>
    const form = document.getElementById('uploadForm');
    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      const formData = new FormData(form);

      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData
      });

      if (response.ok) {
        const data = await response.json();
        const fullUrl = `${window.location.origin}${data.link}`;
        document.getElementById('result').innerHTML = `
          File uploaded successfully!<br>
          Share this link: <a href="${fullUrl}">${fullUrl}</a>
        `;
      } else {
        alert('Upload failed.');
      }
    });
  </script>
</body>
</html>
```

#### Download Page (`public/download.html`)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Download Protected File</title>
  <style>
    body { font-family: sans-serif; max-width: 500px; margin: 50px auto; padding: 20px; }
    form { display: flex; flex-direction: column; gap: 10px; }
  </style>
</head>
<body>
  <h2>Download File</h2>
  <p>This file is password-protected. Enter the password to download.</p>

  <form id="downloadForm">
    <input type="password" id="password" placeholder="Enter password" required>
    <button type="submit">Download</button>
  </form>
  <p id="error" style="color: red;"></p>

  <script>
    const urlParams = new URLSearchParams(window.location.search);
    const fileId = urlParams.get('id');

    document.getElementById('downloadForm').addEventListener('submit', async (e) => {
      e.preventDefault();
      const password = document.getElementById('password').value;
      const errorEl = document.getElementById('error');
      errorEl.innerText = '';

      const response = await fetch(`/api/download/${fileId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password })
      });

      if (response.ok) {
        // Trigger browser download via Blob
        const blob = await response.blob();

        // Extract filename from header if present, or use default
        const disposition = response.headers.get('Content-Disposition');
        let filename = 'downloaded-file';
        if (disposition && disposition.includes('filename=')) {
          filename = disposition.split('filename=')[1].replace(/["']/g, '');
        }

        const downloadUrl = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = downloadUrl;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        a.remove();
      } else {
        const errText = await response.text();
        errorEl.innerText = errText || 'Failed to download file.';
      }
    });
  </script>
</body>
</html>
```

---

### 4. Running the Application

1. Start the server:
   ```bash
   node server.js
   ```
2. Open your browser and go to:
   ```
   http://localhost:3000
   ```
3. Upload a file with a password.
4. Copy the generated link and open it in a private/incognito window to verify the download requires the correct password.

### Security Highlights:
* **Private Storage**: Files are saved in `./uploads/`, which is **not** served statically by `express.static()`. They cannot be accessed directly by URL without going through the `POST /api/download/:id` endpoint.
* **Hashed Passwords**: `bcryptjs` hashes passwords with a work factor (salt rounds = 10) before saving them to SQLite.
* **Server-Side Validation**: Verification is performed strictly on the server using `bcrypt.compare()`. The database record and password hashes are never exposed to the client.

